<script lang="ts">
import snapshot from '$lib/community/data.json';import {channels,formatDate} from '$lib/community/channels';
let {records=snapshot.activity}=$props<{records?:any[]}>();let q=$state('');let channel=$state('all');let visible=$derived(records.filter((a:any)=>(channel==='all'||a.channel===channel)&&((a.title+' '+a.author).toLowerCase().includes(q.toLowerCase()))));
</script>
<section class="activity-browser"><div class="filter-row"><label>Search captured activity<input type="search" bind:value={q} placeholder="Topic or contributor"/></label><label>Channel<select bind:value={channel}><option value="all">All channels</option>{#each channels as c (c.id)}<option value={c.id}>{c.name}</option>{/each}</select></label></div><p class="small" aria-live="polite">{visible.length} captured records</p><ol class="activity-list">{#each visible as a (a.id)}<li><time datetime={a.timestamp}>{formatDate(a.date)}</time><div><a href={a.source}>{a.title} ↗</a><p>{a.kind==='edit'?'Comment edited':a.kind==='comment'?(a.parentComment?'Reply':'Comment'):a.kind==='thread'?'Discussion opened':a.kind==='meeting'?'Meeting / recording':'Published update'} · {a.author==='FedRAMP'?'FedRAMP':'@'+a.author} · {channels.find(c=>c.id===a.channel)?.name}</p></div></li>{/each}</ol>{#if !visible.length}<p>No matching records. Try another channel or search.</p>{/if}</section>
